def domain_flag_graph(a,b,limit=50000):
 keys=('cf','zf','sf','of','pf'); unknown=0xffffffff
 pending=[(a,unknown)];seen={};nodes={};edges={};bad=set();outside=set();indirect=set();proofs=[]
 single={'jb':(0,1),'jc':(0,1),'jnae':(0,1),'jae':(0,0),'jnb':(0,0),'jnc':(0,0),'jz':(1,1),'je':(1,1),'jnz':(1,0),'jne':(1,0),'js':(2,1),'jns':(2,0),'jo':(3,1),'jno':(3,0),'jp':(4,1),'jpe':(4,1),'jnp':(4,0),'jpo':(4,0)}
 preserve={'mov','movzx','movsx','movsxd','lea','push','pop','nop','movaps','movups','movdqa','movdqu','movq','movd','pshufd','punpcklqdq','pxor','xorps','xorps','bswap','xchg','not','cdqe','cqo','cld','std','endbr64'}
 while pending:
  ea,flags=pending.pop()
  previous=seen.get(ea,0)
  if flags & ~previous == 0:continue
  seen[ea]=previous|flags
  if len(seen)>limit:raise RuntimeError('bounded flag graph state limit')
  if not a<=ea<b:outside.add(ea);continue
  ii=ida_ua.insn_t()
  if not ida_ua.decode_insn(ii,ea) or ea+ii.size>b:bad.add(ea);continue
  nodes[ea]=ii;m=ii.get_canon_mnem().lower();nxt=ea+ii.size;ts=[]

  if m.startswith('j') and m!='jmp':
   target=ii.ops[0].addr;tm=0;fm=0
   for bits in range(32):
    if not flags & (1<<bits):continue
    cf,zf,sf,of,pf=[(bits>>k)&1 for k in range(5)]
    if m in single:
     k,v=single[m];take=((bits>>k)&1)==v
    elif m in ('ja','jnbe'):take=not cf and not zf
    elif m in ('jbe','jna'):take=bool(cf or zf)
    elif m in ('jg','jnle'):take=not zf and sf==of
    elif m in ('jle','jng'):take=bool(zf or sf!=of)
    elif m in ('jl','jnge'):take=sf!=of
    elif m in ('jge','jnl'):take=sf==of
    else:tm|=1<<bits;fm|=1<<bits;continue
    if take:tm|=1<<bits
    else:fm|=1<<bits
   if tm:ts.append((target,tm))
   if fm:ts.append((nxt,fm))
   if not tm or not fm:proofs.append({'ea':ea,'condition':m,'domain':flags,'taken':not fm,'selected':target if not fm else nxt})
  elif m=='jmp':
   if ii.ops[0].type==ida_ua.o_near:ts=[(ii.ops[0].addr,flags)]
   else:
    si=ida_nalt.get_switch_info(ea);cs=ida_xref.calc_switch_cases(ea,si) if si else None
    if cs:ts=[(t,flags) for t in cs.targets]
    else:indirect.add(ea)
  elif m in ('ret','retn','retf','iret','int3','ud2'):pass
  else:
   nf=flags if m in preserve or m.startswith('cmov') or m.startswith('set') else unknown
   if m in ('and','or','xor','test'):
    nf=sum(1<<bits for bits in range(32) if not bits&9)
    o0,o1=ii.ops[0],ii.ops[1]
    same=o0.type==ida_ua.o_reg and o1.type==ida_ua.o_reg and o0.reg==o1.reg
    if m=='xor' and same:nf=1<<18
    if m=='or' and o1.type==ida_ua.o_imm and o1.value:nf=sum(1<<bits for bits in range(32) if not bits&11)
    if m=='and' and o1.type==ida_ua.o_imm and not o1.value:nf=1<<18
   if m in ('cmp','sub'):
    o0,o1=ii.ops[0],ii.ops[1]
